<script setup>
import {computed,ref,reactive,watch,nextTick} from 'vue'
import {useRoute} from 'vue-router'
import {informationPages,faq,validateContact} from '../information.js'
const route=useRoute()
const page=computed(()=>informationPages.find(item=>item.name===route.name))
const search=ref(''), category=ref('Tous'), form=ref(null), done=ref(false), errors=ref({})
const fields=reactive({name:'',email:'',subject:'',message:''})
const categories=['Tous',...new Set(faq.map(item=>item.category))]
const results=computed(()=>faq.filter(item=>(category.value==='Tous'||item.category===category.value)&&`${item.question} ${item.answer}`.toLocaleLowerCase('fr').includes(search.value.trim().toLocaleLowerCase('fr'))))
watch(()=>route.name,()=>{search.value='';category.value='Tous';done.value=false;errors.value={};Object.keys(fields).forEach(key=>fields[key]='')})
async function submit(){errors.value=validateContact(fields);if(Object.keys(errors.value).length){await nextTick();form.value?.querySelector('[aria-invalid=true]')?.focus();return}Object.keys(fields).forEach(key=>fields[key]='');done.value=true;await nextTick();document.getElementById('contact-result')?.focus()}
</script>
<template>
<section class="container section information-page"><nav class="breadcrumb" aria-label="Fil d’Ariane"><RouterLink :to="{name:'home'}">Accueil</RouterLink><span aria-hidden="true">/</span><span aria-current="page">{{page?.title||(route.name==='help'?'Aide et questions fréquentes':'Contact')}}</span></nav>
<header class="information-heading"><span class="eyebrow coral">À VOS CÔTÉS, TOUT SIMPLEMENT</span><h1>{{page?.title||(route.name==='help'?'Comment vous aider ?':'Parlons de vos envies.')}}</h1><p>{{page?.intro||(route.name==='help'?'Les réponses pour explorer NovaShop en toute clarté.':'Essayez le formulaire avec des informations fictives. Aucun message ne sera envoyé.')}}</p></header>
<div class="information-workspace"><nav class="information-nav" aria-label="Informations et assistance"><RouterLink v-for="item in [{name:'help',title:'Aide et FAQ'},{name:'contact',title:'Contact'},...informationPages]" :key="item.name" :to="{name:item.name}" :aria-current="route.name===item.name?'page':undefined">{{item.title}}</RouterLink></nav>
<div class="information-content">
<template v-if="page"><p v-if="['terms','legal','privacy'].includes(page.name)" class="account-demo-banner">Contenu de démonstration à compléter pour l’exploitant et le déploiement réels. Boutique non ouverte à la vente.</p><section v-for="[heading,text] in page.sections" :key="heading" class="information-section"><h2>{{heading}}</h2><p>{{text}}</p></section><RouterLink class="text-link" :to="{name:'contact'}">Une question ? Voir le formulaire de contact</RouterLink></template>
<template v-else-if="route.name==='help'"><div class="faq-tools"><label for="faq-search">Rechercher une réponse<input id="faq-search" v-model="search" type="search" maxlength="120" placeholder="Panier, livraison, compte…"/></label><label for="faq-category">Thème<select id="faq-category" v-model="category"><option v-for="item in categories" :key="item">{{item}}</option></select></label></div><p role="status">{{results.length}} réponse(s)</p><details v-for="item in results" :key="item.question" class="faq-item"><summary>{{item.question}}</summary><p>{{item.answer}}</p><RouterLink class="text-link" :to="{name:item.to}">{{item.label}}</RouterLink></details><div v-if="!results.length" class="empty-state"><h2>Aucune réponse trouvée.</h2><button class="button button-dark" @click="search='';category='Tous'">Réinitialiser la recherche</button></div><RouterLink class="text-link information-contact-link" :to="{name:'contact'}">Voir le formulaire de contact</RouterLink></template>
<template v-else><div class="account-panel"><h2>Contact de démonstration</h2><p>Les coordonnées réelles du service client ne sont pas encore définies. Aucun délai de réponse n’est annoncé.</p><template v-if="done"><h3 id="contact-result" tabindex="-1">Formulaire validé, aucun message envoyé.</h3><p role="status">La saisie a été effacée. Aucun message ni adresse e-mail n’a été conservé.</p><button class="button button-dark" @click="done=false">Essayer à nouveau</button></template><form v-else ref="form" @submit.prevent="submit" novalidate><p>Utilisez des données fictives. N’indiquez aucun mot de passe, numéro de carte ou document personnel.</p><label for="contact-name">Nom fictif<input id="contact-name" aria-label="Nom fictif" v-model="fields.name" maxlength="100" autocomplete="off" required :aria-invalid="Boolean(errors.name)" aria-describedby="contact-name-error"/><span id="contact-name-error" class="field-error">{{errors.name}}</span></label><label for="contact-email">E-mail fictif<input id="contact-email" aria-label="E-mail fictif" v-model="fields.email" type="email" maxlength="254" autocomplete="off" required :aria-invalid="Boolean(errors.email)" aria-describedby="contact-email-error"/><span id="contact-email-error" class="field-error">{{errors.email}}</span></label><label for="contact-subject">Sujet<select id="contact-subject" aria-label="Sujet" v-model="fields.subject" required :aria-invalid="Boolean(errors.subject)" aria-describedby="contact-subject-error"><option value="">Choisir un sujet</option><option value="product">Un produit</option><option value="order">Le parcours de commande</option><option value="other">Autre question</option></select><span id="contact-subject-error" class="field-error">{{errors.subject}}</span></label><label for="contact-message">Message fictif<textarea id="contact-message" aria-label="Message fictif" v-model="fields.message" maxlength="2000" rows="6" required :aria-invalid="Boolean(errors.message)" aria-describedby="contact-message-error"/><span id="contact-message-error" class="field-error">{{errors.message}}</span></label><button class="button button-dark">Simuler l’envoi</button><p><RouterLink :to="{name:'privacy'}">Comprendre la confidentialité du prototype</RouterLink></p></form></div></template>
</div></div></section>
</template>
